-- Раздел «О департаменте»
INSERT INTO sections (id, slug, title, description, sort) VALUES (1, 'about', 'О департаменте', 'Полномочия, руководство, структура и история департамента лесного хозяйства Заречной области.', 1);
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (1, 1, 'polnomochiya', 'Полномочия департамента', 'Департамент лесного хозяйства — исполнительный орган Заречной области, который управляет лесами на территории региона и осуществляет переданные Российской Федерацией полномочия в области лесных отношений.', '<p>Департамент лесного хозяйства Заречной области (далее — департамент) входит в систему исполнительных органов области. В своей работе он руководствуется Лесным кодексом Российской Федерации, федеральными законами, законами Заречной области и Положением о департаменте, утверждённым постановлением правительства области.</p>
<p>Большая часть полномочий в сфере лесных отношений передана регионам статьёй 83 Лесного кодекса. Их финансирование идёт за счёт субвенций из федерального бюджета, а контроль качества исполнения ведёт Федеральное агентство лесного хозяйства.</p>
<h2>Основные полномочия</h2>
<ul>
<li>предоставление лесных участков в постоянное (бессрочное) пользование, аренду и безвозмездное пользование;</li>
<li>заключение договоров купли-продажи лесных насаждений, в том числе для собственных нужд граждан;</li>
<li>организация охраны лесов от пожаров, их защиты от вредных организмов, воспроизводства лесов и лесоразведения;</li>
<li>федеральный государственный лесной контроль (надзор) и федеральный государственный пожарный надзор в лесах;</li>
<li>ведение государственного лесного реестра в отношении лесов области;</li>
<li>разработка лесного плана Заречной области и лесохозяйственных регламентов лесничеств;</li>
<li>рассмотрение обращений граждан и организаций по вопросам, отнесённым к ведению департамента.</li>
</ul>
<h2>Чего департамент не делает</h2>
<p>В ведении департамента находятся только земли лесного фонда. Городские леса, лесопарки и деревья во дворах относятся к ведению органов местного самоуправления, а особо охраняемые природные территории федерального значения — к ведению Минприроды России. Если вопрос касается этих территорий, обращение будет перенаправлено по принадлежности в течение семи дней.</p>', 'about-polnomochiya.jpg', NULL, 1, 77, '2025-11-03 10:00');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (2, 1, 'rukovodstvo', 'Руководство департамента', 'Директор департамента, его заместители и распределение обязанностей между ними. Сведения о графике личного приёма граждан.', '<h2>Директор департамента</h2>
<p><strong>Савельев Андрей Николаевич</strong></p>
<p>Руководит деятельностью департамента, несёт персональную ответственность за выполнение возложенных на него полномочий. Курирует вопросы охраны лесов от пожаров и взаимодействия с Рослесхозом.</p>
<p>Личный приём граждан — первый вторник месяца с 14:00 до 17:00. Предварительная запись по телефону +7 (3800) 41-02-05.</p>
<h2>Заместители директора</h2>
<table>
<thead><tr><th>Должность</th><th>ФИО</th><th>Курируемые направления</th></tr></thead>
<tbody>
<tr><td>Первый заместитель директора</td><td>Корнилова Елена Викторовна</td><td>лесопользование, аренда лесных участков, государственный лесной реестр</td></tr>
<tr><td>Заместитель директора — начальник отдела лесного контроля</td><td>Гречко Павел Сергеевич</td><td>федеральный государственный лесной контроль, работа лесничеств</td></tr>
<tr><td>Заместитель директора</td><td>Мансурова Ольга Ринатовна</td><td>воспроизводство и защита лесов, лесной семеноводческий центр</td></tr>
</tbody>
</table>
<p>Во время отсутствия директора его обязанности исполняет первый заместитель. Вопросы, требующие решения руководства, можно направить через <a href="/appeals">интернет-приёмную</a> — обращение будет передано профильному заместителю.</p>', 'about-rukovodstvo.jpg', NULL, 1, 114, '2025-11-03 10:05');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (3, 1, 'struktura', 'Структура департамента', 'Отделы центрального аппарата, территориальные лесничества и подведомственные учреждения департамента.', '<p>Работу департамента обеспечивают центральный аппарат в г. Заречинске, 14 лесничеств и два подведомственных государственных учреждения. Численность центрального аппарата — 64 штатные единицы, лесничеств — 212.</p>
<h2>Центральный аппарат</h2>
<ul>
<li>отдел охраны и защиты леса;</li>
<li>отдел лесопользования и аренды;</li>
<li>отдел воспроизводства лесов;</li>
<li>отдел федерального государственного лесного контроля (надзора);</li>
<li>отдел государственного лесного реестра и лесоустройства;</li>
<li>финансово-экономический отдел;</li>
<li>отдел правового и кадрового обеспечения;</li>
<li>отдел по работе с обращениями граждан и пресс-служба.</li>
</ul>
<h2>Лесничества</h2>
<p>Лесничества — территориальные отделы департамента. Именно туда граждане подают документы на заготовку древесины для собственных нужд, там же можно получить консультацию по границам лесных участков и правилам пребывания в лесу. Адреса и телефоны лесничеств приведены в разделе <a href="/contacts">«Контакты»</a>.</p>
<h2>Подведомственные учреждения</h2>
<ul>
<li><strong>ГАУ «Заречный лесопожарный центр»</strong> — тушение лесных пожаров, авиационное и наземное патрулирование, работа региональной диспетчерской службы;</li>
<li><strong>ГБУ «Заречный лесной селекционно-семеноводческий центр»</strong> — заготовка семян, выращивание сеянцев и саженцев, в том числе с закрытой корневой системой.</li>
</ul>', 'about-struktura.jpg', NULL, 1, 151, '2025-11-03 10:10');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (4, 1, 'istoriya', 'История лесного ведомства области', 'От первых казённых лесничеств конца XIX века до современного департамента: как менялось управление лесами в регионе.', '<p>Первые казённые лесничества на территории нынешней Заречной области появились в 1880-х годах. Их задачей было прежде всего обеспечить лесом строительство железной дороги и заводов, поэтому учёт и охрану лесов вели в первую очередь вдоль рек, по которым сплавляли древесину.</p>
<h2>XX век</h2>
<p>В 1930-е годы в области создали лесхозы, которые совмещали хозяйственную деятельность с охраной лесов. После войны главной задачей стало восстановление вырубленных массивов: только за 1946–1960 годы лесхозы области заложили более 180 тысяч гектаров лесных культур. В 1957 году была организована авиабаза охраны лесов, а в 1970-х — первый в регионе лесной питомник с поливом.</p>
<h2>Новейшая история</h2>
<p>После принятия Лесного кодекса 2006 года хозяйственные и контрольные функции разделили. Лесхозы были преобразованы: контроль и управление перешли к лесничествам, а работы по охране и воспроизводству лесов — к подрядным организациям и государственным учреждениям. В 2019 году управление лесами области было реорганизовано в департамент лесного хозяйства.</p>
<blockquote>За 140 лет лесистость территории области почти не изменилась и сегодня составляет 57,4 %. Это результат работы нескольких поколений лесоводов.</blockquote>', 'about-istoriya.jpg', NULL, 1, 188, '2025-11-03 10:15');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (5, 1, 'gossluzhba-i-vakansii', 'Государственная служба и вакансии', 'Как поступить на государственную гражданскую службу в департамент, какие вакансии открыты сейчас и какие документы нужны для участия в конкурсе.', '<p>Поступление на государственную гражданскую службу Заречной области проводится по конкурсу в соответствии с Федеральным законом от 27.07.2004 № 79-ФЗ «О государственной гражданской службе Российской Федерации».</p>
<h2>Открытые вакансии</h2>
<table>
<thead><tr><th>Должность</th><th>Подразделение</th><th>Требования</th></tr></thead>
<tbody>
<tr><td>Главный специалист</td><td>отдел лесного контроля</td><td>высшее образование по направлению «Лесное дело», опыт не требуется</td></tr>
<tr><td>Ведущий специалист — участковый лесничий</td><td>Таёжное лесничество</td><td>высшее или среднее профессиональное лесное образование, водительское удостоверение категории B</td></tr>
<tr><td>Консультант</td><td>отдел государственного лесного реестра</td><td>высшее образование, знание ГИС-программ, опыт работы от 1 года</td></tr>
</tbody>
</table>
<h2>Документы для участия в конкурсе</h2>
<ul>
<li>личное заявление и анкета установленной формы с фотографией;</li>
<li>копия паспорта, документов об образовании и трудовой книжки (сведений о трудовой деятельности);</li>
<li>заключение медицинской организации об отсутствии заболеваний, препятствующих поступлению на службу.</li>
</ul>
<p>Документы принимаются в течение 21 дня со дня объявления конкурса в отделе правового и кадрового обеспечения (каб. 214) или через портал «Работа в России».</p>', 'about-gossluzhba-i-vakansii.jpg', NULL, 1, 225, '2025-11-03 10:20');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (6, 1, 'protivodeystvie-korruptsii', 'Противодействие коррупции', 'Меры по профилактике коррупционных правонарушений в департаменте и порядок сообщения о фактах коррупции.', '<p>В департаменте действует план противодействия коррупции на 2024–2026 годы. За профилактику коррупционных правонарушений отвечает отдел правового и кадрового обеспечения.</p>
<h2>Что делает департамент</h2>
<ul>
<li>проверяет сведения о доходах, расходах и имуществе государственных служащих;</li>
<li>проводит антикоррупционную экспертизу проектов приказов;</li>
<li>рассматривает на заседаниях комиссии случаи конфликта интересов;</li>
<li>переводит услуги в электронный вид, чтобы уменьшить число личных контактов заявителей с должностными лицами.</li>
</ul>
<h2>Как сообщить о коррупции</h2>
<p>Если вам стало известно о склонении служащего департамента к коррупционному правонарушению или о вымогательстве, сообщите об этом по телефону доверия +7 (3800) 41-02-77 или через <a href="/appeals">интернет-приёмную</a>, выбрав тематику «Другое». Конфиденциальность заявителя гарантируется.</p>', 'about-protivodeystvie-korruptsii.jpg', NULL, 1, 262, '2025-11-03 10:25');

-- Раздел «Новости»
INSERT INTO sections (id, slug, title, description, sort) VALUES (2, 'news', 'Новости', 'События и официальные сообщения департамента.', 2);
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (7, 2, 'zavershen-pozharoopasnyy-sezon-2025', 'Пожароопасный сезон 2025 года в области завершён', 'С 15 октября на всей территории Заречной области завершён пожароопасный сезон. За сезон зарегистрировано 96 лесных пожаров, на 31 % меньше, чем годом ранее.', '<p>Решение о завершении пожароопасного сезона принято с учётом установившейся дождливой погоды и прогноза синоптиков. Сезон длился 183 дня — с 14 апреля по 14 октября.</p>
<p>Всего за сезон в лесах области зарегистрировано 96 лесных пожаров на общей площади 1 214 гектаров. Годом ранее пожаров было 139, а площадь превышала 4,7 тысячи гектаров. 87 % возгораний удалось ликвидировать в первые сутки после обнаружения.</p>
<p>«Главное, что изменилось в этом году, — скорость обнаружения. Камеры видеомониторинга заметили почти половину всех пожаров, причём в среднем через 12 минут после появления дыма», — отметил директор департамента Андрей Савельев.</p>
<p>Основной причиной пожаров по-прежнему остаётся неосторожное обращение с огнём: на него пришлось 71 % случаев. Ещё 18 % возгораний вызваны грозами.</p>', 'news-zavershen-pozharoopasnyy-sezon-2025.jpg', NULL, 2, 299, '2025-10-14 11:20');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (8, 2, 'osennyaya-posadka-lesa', 'Осенью в области высажено более 3 миллионов сеянцев', 'Завершилась осенняя кампания по лесовосстановлению: лесные культуры созданы на площади 1,1 тысячи гектаров.', '<p>Осенняя посадка леса прошла в девяти лесничествах области. Основная часть работ выполнена на гарях прошлых лет в Таёжном и Верхнекаменском лесничествах.</p>
<p>Высаживались сеянцы сосны обыкновенной и ели сибирской с закрытой корневой системой, выращенные в Заречном лесном селекционно-семеноводческом центре. Такие растения сажают вместе с комом земли, поэтому корни не пересыхают и приживаемость достигает 90 %.</p>
<p>В посадке приняли участие сотрудники лесничеств, арендаторы лесных участков, а также более 600 волонтёров. Всего с начала года лесовосстановление проведено на площади 31,2 тысячи гектаров, что на 2 % больше плана.</p>', 'news-osennyaya-posadka-lesa.jpg', NULL, 2, 76, '2025-10-22 15:00');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (9, 2, 'nezakonnaya-rubka-tayozhnoe', 'В Таёжном лесничестве пресечена незаконная рубка', 'Государственные лесные инспекторы во время рейда обнаружили бригаду, которая вела рубку сосны без документов. Ущерб оценивается в 3,2 миллиона рублей.', '<p>Рейд проводился совместно с сотрудниками полиции после сообщения местного жителя на прямую линию лесной охраны. В квартале 214 Таёжного участкового лесничества инспекторы обнаружили четырёх человек, харвестер и лесовоз.</p>
<p>Разрешительных документов у бригады не оказалось. По предварительным данным, вырублено 186 кубометров сосны. Сумма ущерба, рассчитанная по таксам, составила 3,2 миллиона рублей.</p>
<p>Материалы переданы в полицию для решения вопроса о возбуждении уголовного дела по статье 260 Уголовного кодекса РФ. Техника изъята.</p>
<p>Департамент благодарит жителя посёлка Таёжный за неравнодушие. Напоминаем: сообщить о подозрительной рубке можно круглосуточно по телефону 8-800-100-94-00.</p>', 'news-nezakonnaya-rubka-tayozhnoe.jpg', NULL, 2, 113, '2025-11-05 10:40');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (10, 2, 'novye-teplitsy-seleksionnogo-tsentra', 'Селекционно-семеноводческий центр ввёл в работу новые теплицы', 'Два тепличных комплекса площадью 3 тысячи квадратных метров позволят выращивать до 5 миллионов сеянцев с закрытой корневой системой в год.', '<p>Теплицы построены на территории питомника в посёлке Сосновый Бор в рамках федерального проекта «Сохранение лесов». В комплексах установлены автоматические системы полива, подкормки и проветривания, а также линия посева семян в кассеты.</p>
<p>С вводом новых теплиц мощность центра по выращиванию посадочного материала с закрытой корневой системой увеличится почти вдвое. Это позволит полностью обеспечить потребности области и отказаться от закупки сеянцев в соседних регионах.</p>
<p>Первый посев в новых теплицах запланирован на март 2026 года.</p>', 'news-novye-teplitsy-seleksionnogo-tsentra.jpg', NULL, 2, 150, '2025-11-12 12:15');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (11, 2, 'itogi-akcii-sohranim-les', 'Итоги акции «Сохраним лес»: высажено 48 тысяч деревьев', 'В акции приняли участие более 2,5 тысячи жителей области — школьники, студенты, сотрудники предприятий и семьи с детьми.', '<p>Акция проходила с сентября по октябрь на 23 площадках в разных районах области. Самой массовой стала посадка у села Озёрное, где за один день участники высадили почти 9 тысяч сеянцев сосны.</p>
<p>Впервые в акции участвовали студенты Заречного аграрного колледжа: они не только сажали деревья, но и помогали специалистам лесничеств инструктировать волонтёров.</p>
<p>«Каждая посадка — это не только новые деревья, но и люди, которые потом будут беречь этот лес», — говорит заместитель директора департамента Ольга Мансурова.</p>
<p>Следующая акция пройдёт весной 2026 года. Следите за новостями, чтобы не пропустить регистрацию.</p>', 'news-itogi-akcii-sohranim-les.jpg', NULL, 2, 187, '2025-11-19 16:30');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (12, 2, 'novogodnie-eli-zakonno', 'Новогодняя ель: как купить законно и не нарушить закон', 'Перед праздниками департамент усиливает рейды против незаконной вырубки хвойных деревьев. Рассказываем, где можно купить ель и как получить разрешение на заготовку.', '<p>С 1 по 31 декабря в лесах области проводятся рейды по предотвращению незаконной рубки новогодних елей. Штраф за самовольную вырубку даже одного дерева для граждан составляет от 3 до 3,5 тысячи рублей плюс возмещение ущерба.</p>
<p>Законно приобрести ель можно на ёлочных базарах, где у продавцов есть документы о происхождении деревьев, а также в лесничествах. В этом году лесничества подготовили более 4 тысяч деревьев из расчищаемых охранных зон линий электропередачи и молодняков, где проводятся рубки ухода.</p>
<p>Жители также могут заключить договор на заготовку новогодней ели самостоятельно. Для этого нужно обратиться в лесничество с паспортом: специалист укажет участок и выдаст документ, который нужно иметь при себе при вывозе дерева.</p>', 'news-novogodnie-eli-zakonno.jpg', NULL, 2, 224, '2025-11-27 10:00');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (13, 2, 'povyshenie-kvalifikatsii-lesnoy-ohrany', 'Инспекторы лесной охраны прошли повышение квалификации', 'Обучение по программе «Федеральный государственный лесной контроль (надзор)» прошли 42 государственных лесных инспектора.', '<p>Занятия проходили на базе учебного центра Заречного аграрного университета. Программа включала изменения законодательства о государственном контроле, работу с ФГИС лесного комплекса, расчёт ущерба от лесонарушений и использование беспилотников при патрулировании.</p>
<p>Практические занятия провели в Заречинском лесничестве: инспекторы отрабатывали составление протоколов осмотра и фиксацию нарушений с помощью мобильного приложения.</p>
<p>По итогам обучения все участники успешно сдали итоговое тестирование и получили удостоверения установленного образца.</p>', 'news-povyshenie-kvalifikatsii-lesnoy-ohrany.jpg', NULL, 2, 261, '2025-12-04 14:20');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (14, 2, 'zapushchen-novyy-sayt', 'Департамент запустил обновлённый сайт', 'На новом сайте появились интернет-приёмная с личным кабинетом, поиск по материалам, карта сайта и версия для слабовидящих.', '<p>Обновлённый сайт департамента начал работу в декабре. Главная цель изменений — сделать информацию о лесах области понятнее и сократить путь от вопроса до ответа.</p>
<h2>Что нового</h2>
<ul>
<li><strong>Интернет-приёмная.</strong> Обращение можно направить после регистрации, а ответ специалиста придёт в личный кабинет. По каждому обращению сохраняется переписка, поэтому уточнить детали можно, не составляя новое письмо.</li>
<li><strong>Версия для слабовидящих.</strong> Можно увеличить шрифт, выбрать контрастную цветовую схему, отключить изображения и увеличить интервалы между буквами и строками.</li>
<li><strong>Поиск по сайту</strong> по всем новостям, документам и материалам разделов.</li>
<li><strong>Раздел «Гражданам»</strong> с пошаговыми инструкциями по самым частым вопросам.</li>
</ul>
<p>Если вы заметили ошибку в работе сайта или хотите предложить улучшения, напишите нам через <a href="/appeals">интернет-приёмную</a>, выбрав тематику «Работа сайта».</p>', 'news-zapushchen-novyy-sayt.jpg', NULL, 2, 298, '2025-12-22 09:30');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (15, 2, 'utverzhden-plan-tusheniya-2026', 'Утверждён сводный план тушения лесных пожаров на 2026 год', 'Губернатор области подписал указ об утверждении сводного плана. В 2026 году к охране лесов будет привлечено 412 человек и 137 единиц техники.', '<p>Сводный план тушения лесных пожаров ежегодно утверждается до начала пожароопасного сезона и согласовывается с Рослесхозом. В нём определены силы и средства, порядок их привлечения и схема взаимодействия всех служб.</p>
<p>В 2026 году лесопожарный центр получит шесть новых пожарных автомобилей и два трактора с плугами для прокладки минерализованных полос. Также планируется расширить сеть видеомониторинга ещё на 12 камер в северных районах области.</p>
<p>Полный текст документа размещён в разделе <a href="/documents/plan-tusheniya-pozharov-2026">«Документы»</a>.</p>', 'news-utverzhden-plan-tusheniya-2026.jpg', NULL, 2, 75, '2025-12-16 11:00');

-- Раздел «Деятельность»
INSERT INTO sections (id, slug, title, description, sort) VALUES (3, 'activity', 'Деятельность', 'Основные направления работы: охрана, защита и воспроизводство лесов, лесной контроль и лесопользование.', 3);
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (16, 3, 'ohrana-lesov-ot-pozharov', 'Охрана лесов от пожаров', 'Как в области организованы профилактика, обнаружение и тушение лесных пожаров, кто отвечает за каждый этап и что делать при обнаружении возгорания.', '<p>Охрана лесов от пожаров — главная задача департамента с апреля по октябрь. Пожароопасный сезон в Заречной области обычно начинается в середине апреля, сразу после схода снега, и заканчивается с наступлением устойчивой дождливой погоды.</p>
<h2>Как организована работа</h2>
<ul>
<li><strong>Профилактика.</strong> Устройство и обновление минерализованных полос, противопожарная пропаганда, контроль за соблюдением правил пожарной безопасности арендаторами.</li>
<li><strong>Обнаружение.</strong> Наземное патрулирование, авиационный мониторинг, система видеонаблюдения из 46 камер на вышках сотовой связи и данные спутникового мониторинга.</li>
<li><strong>Тушение.</strong> Работы ведёт ГАУ «Заречный лесопожарный центр», в составе которого 9 пожарно-химических станций и группа десантников-пожарных.</li>
</ul>
<h2>Классы пожарной опасности</h2>
<p>Пожарная опасность в лесах по условиям погоды определяется ежедневно по пятибалльной шкале. При IV и V классах может вводиться ограничение пребывания граждан в лесах.</p>
<table>
<thead><tr><th>Класс</th><th>Степень опасности</th><th>Что это значит</th></tr></thead>
<tbody>
<tr><td>I</td><td>отсутствует</td><td>возгорание маловероятно</td></tr>
<tr><td>II</td><td>малая</td><td>возможны локальные загорания на открытых местах</td></tr>
<tr><td>III</td><td>средняя</td><td>огонь распространяется по лесной подстилке</td></tr>
<tr><td>IV</td><td>высокая</td><td>возможен быстрый рост площади пожара</td></tr>
<tr><td>V</td><td>чрезвычайная</td><td>пожар может перейти в верховой</td></tr>
</tbody>
</table>
<div class="warning"><strong>Увидели дым или огонь в лесу?</strong> Звоните на прямую линию лесной охраны 8-800-100-94-00 или по номеру 112. Назовите ближайший населённый пункт или дорогу, примерную площадь и направление дыма.</div>', 'activity-ohrana-lesov-ot-pozharov.jpg', NULL, 1, 112, '2025-11-04 09:00');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (17, 3, 'vosproizvodstvo-lesov', 'Воспроизводство лесов и лесовосстановление', 'Лес после рубки или пожара должен быть восстановлен. Рассказываем, как это делается, кто сажает деревья и как проверяется результат.', '<p>Каждый гектар леса, вырубленного или погибшего от пожара, должен быть восстановлен. Это требование статьи 61 Лесного кодекса. Если участок в аренде, лесовосстановление выполняет арендатор, на остальной территории — департамент через подведомственные учреждения и подрядчиков.</p>
<h2>Способы восстановления</h2>
<ul>
<li><strong>Искусственное</strong> — посадка сеянцев и саженцев. Используется там, где естественное возобновление невозможно, например на старых гарях.</li>
<li><strong>Естественное</strong> — сохранение подроста при рубке, минерализация почвы для прорастания семян.</li>
<li><strong>Комбинированное</strong> — сочетание посадки с содействием естественному возобновлению.</li>
</ul>
<h2>Посадочный материал</h2>
<p>Сеянцы сосны и ели выращивает ГБУ «Заречный лесной селекционно-семеноводческий центр». С 2023 года основная часть материала выращивается с закрытой корневой системой: такие растения приживаются лучше, а сажать их можно с весны до осени.</p>
<h2>Итоги 2025 года</h2>
<table>
<thead><tr><th>Показатель</th><th>План</th><th>Факт</th></tr></thead>
<tbody>
<tr><td>Лесовосстановление, тыс. га</td><td>30,5</td><td>31,2</td></tr>
<tr><td>в том числе искусственное, тыс. га</td><td>9,8</td><td>10,1</td></tr>
<tr><td>Выращено сеянцев, млн шт.</td><td>14,0</td><td>14,6</td></tr>
</tbody>
</table>
<p>Приживаемость культур проверяется через год после посадки, а через 5–8 лет молодые деревья переводятся в покрытые лесом земли.</p>', 'activity-vosproizvodstvo-lesov.jpg', NULL, 1, 149, '2025-11-04 09:10');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (18, 3, 'zaschita-lesov', 'Защита лесов от вредителей и болезней', 'Лесопатологический мониторинг, санитарно-оздоровительные мероприятия и борьба с очагами вредителей — как департамент сохраняет здоровье лесов.', '<p>Ослабленный лес легко становится жертвой короедов, сибирского шелкопряда и грибковых болезней. Задача защиты лесов — вовремя заметить очаг и не дать ему разрастись.</p>
<h2>Лесопатологический мониторинг</h2>
<p>Специалисты ежегодно обследуют насаждения на постоянных пунктах наблюдения. Каждое дерево на пункте оценивается по категории санитарного состояния: от «без признаков ослабления» до «старого сухостоя». По результатам составляется лесопатологический прогноз на следующий год.</p>
<h2>Основные угрозы для лесов области</h2>
<ul>
<li>короед-типограф — поражает ослабленные ельники, особенно после засушливого лета;</li>
<li>сибирский шелкопряд — опасен для пихтовых и кедровых насаждений на севере области;</li>
<li>корневая губка — грибковое заболевание сосновых культур на бедных песчаных почвах.</li>
</ul>
<h2>Санитарно-оздоровительные мероприятия</h2>
<p>В погибших и повреждённых насаждениях проводятся санитарные рубки и уборка захламлённости. Решение о рубке принимается только по акту лесопатологического обследования, который публикуется на сайте Рослесхоза не менее чем за 20 дней до начала работ, — так любой гражданин может проверить его обоснованность.</p>', 'activity-zaschita-lesov.jpg', NULL, 1, 186, '2025-11-04 09:20');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (19, 3, 'lesnoy-kontrol', 'Федеральный государственный лесной контроль (надзор)', 'Кто и как проверяет соблюдение лесного законодательства, какие нарушения встречаются чаще всего и какая ответственность за них предусмотрена.', '<p>Федеральный государственный лесной контроль (надзор) на землях лесного фонда области осуществляют государственные лесные инспекторы департамента и лесничеств. Порядок контроля определён Федеральным законом от 31.07.2020 № 248-ФЗ «О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации».</p>
<h2>Профилактика важнее наказания</h2>
<p>Большая часть работы инспекторов — профилактика: консультирование, объявление предостережений, профилактические визиты к арендаторам. Плановые проверки проводятся только на объектах высокого риска.</p>
<h2>Самые частые нарушения</h2>
<ul>
<li>незаконная рубка лесных насаждений (статья 260 УК РФ, статья 8.28 КоАП РФ);</li>
<li>самовольное занятие лесных участков под огороды, стоянки, склады;</li>
<li>загрязнение лесов бытовыми и строительными отходами;</li>
<li>нарушение правил пожарной безопасности в лесах.</li>
</ul>
<h2>Рейды и патрулирование</h2>
<p>В 2025 году инспекторы провели более 2 300 патрулирований, выявили 418 нарушений лесного законодательства и передали в полицию 37 материалов по фактам незаконной рубки. Сумма возмещённого ущерба составила 21,6 млн рублей.</p>', 'activity-lesnoy-kontrol.jpg', NULL, 1, 223, '2025-11-04 09:30');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (20, 3, 'ispolzovanie-lesov', 'Использование лесов и аренда лесных участков', 'Виды использования лесов, предоставление участков в аренду через аукцион и без торгов, отчётность арендаторов.', '<p>Лесной кодекс предусматривает 17 видов использования лесов — от заготовки древесины до рекреационной деятельности и выращивания лесных ягод. В Заречной области в аренде находится 2,1 млн гектаров, то есть около трети лесного фонда.</p>
<h2>Как предоставляются участки</h2>
<ul>
<li><strong>по результатам аукциона</strong> — для заготовки древесины, рекреации, выращивания лесных растений;</li>
<li><strong>без торгов</strong> — для реализации приоритетных инвестиционных проектов, строительства линейных объектов, геологического изучения недр;</li>
<li><strong>в безвозмездное пользование</strong> — государственным учреждениям, религиозным организациям, гражданам для сенокошения и пчеловодства.</li>
</ul>
<h2>Обязанности арендатора</h2>
<p>Арендатор разрабатывает проект освоения лесов, ежегодно подаёт лесную декларацию и отчёты об использовании, охране и воспроизводстве лесов. Все документы подаются в электронном виде через федеральную государственную информационную систему лесного комплекса.</p>
<p>Подробнее о порядке для граждан и небольших предприятий — в материале <a href="/citizens/arenda-lesnogo-uchastka">«Как взять лесной участок в аренду»</a>.</p>', 'activity-ispolzovanie-lesov.jpg', NULL, 1, 260, '2025-11-04 09:40');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (21, 3, 'lesnoy-reestr', 'Государственный лесной реестр и лесоустройство', 'Что такое лесной реестр, как получить из него выписку и зачем проводится лесоустройство.', '<p>Государственный лесной реестр — систематизированный свод сведений о лесах: их границах, составе, возрасте, запасах древесины и правовом режиме. Реестр ведётся в федеральной государственной информационной системе лесного комплекса.</p>
<h2>Как получить выписку</h2>
<p>Выписка из государственного лесного реестра предоставляется бесплатно в течение 10 рабочих дней. Запрос можно подать:</p>
<ul>
<li>через портал Госуслуг;</li>
<li>лично в отделе государственного лесного реестра (каб. 318);</li>
<li>почтой по адресу департамента.</li>
</ul>
<p>В запросе укажите лесничество, участковое лесничество, номер квартала и выдела. Если этих данных нет, приложите схему участка или координаты.</p>
<h2>Лесоустройство</h2>
<p>Лесоустройство — это инвентаризация лесов, которая повторяется раз в 10–15 лет. В 2024–2025 годах лесоустроительные работы проведены в Озёрском и Сосновоборском лесничествах на площади 1,08 млн гектаров. Новые материалы уже внесены в лесной реестр и учтены в лесохозяйственных регламентах.</p>', 'activity-lesnoy-reestr.jpg', NULL, 1, 297, '2025-11-04 09:50');

-- Раздел «Гражданам»
INSERT INTO sections (id, slug, title, description, sort) VALUES (4, 'citizens', 'Гражданам', 'Пошаговые инструкции и ответы на частые вопросы жителей области.', 4);
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (22, 4, 'zagotovka-drevesiny-dlya-sobstvennyh-nuzhd', 'Заготовка древесины для собственных нужд', 'Кто имеет право купить лес на корню для строительства дома или отопления, сколько это стоит и как подать заявление через лесничество или Госуслуги.', '<p>Граждане вправе заготавливать древесину для отопления, возведения и ремонта жилых домов и хозяйственных построек (статья 30 Лесного кодекса РФ). Для этого с департаментом заключается договор купли-продажи лесных насаждений. Нормативы и порядок заготовки установлены законом Заречной области от 30.06.2022 № 41-ЗО.</p>
<h2>Нормативы заготовки</h2>
<table>
<thead><tr><th>Цель</th><th>Объём</th><th>Периодичность</th></tr></thead>
<tbody>
<tr><td>Строительство жилого дома</td><td>до 150 м³</td><td>один раз в 30 лет</td></tr>
<tr><td>Ремонт жилого дома</td><td>до 25 м³</td><td>один раз в 10 лет</td></tr>
<tr><td>Строительство хозяйственных построек</td><td>до 30 м³</td><td>один раз в 20 лет</td></tr>
<tr><td>Отопление жилого дома (дрова)</td><td>до 20 м³</td><td>ежегодно</td></tr>
</tbody>
</table>
<h2>Как оформить</h2>
<ol>
<li>Подайте заявление в лесничество по месту нахождения дома или через портал Госуслуг. Для строительства приложите разрешение или уведомление о строительстве, для отопления — документ о печном отоплении дома.</li>
<li>В течение 15 рабочих дней лесничество подготовит договор и рассчитает плату по ставкам, утверждённым приказом департамента.</li>
<li>После оплаты получите в лесничестве разметку лесосеки и начинайте заготовку. Вывезти древесину нужно до окончания срока действия договора — как правило, в течение года.</li>
</ol>
<div class="warning"><strong>Важно:</strong> продавать или передавать третьим лицам древесину, заготовленную для собственных нужд, запрещено. За это предусмотрена административная ответственность.</div>', 'citizens-zagotovka-drevesiny-dlya-sobstvennyh-nuzhd.jpg', NULL, 2, 74, '2025-11-05 09:00');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (23, 4, 'pravila-pozharnoy-bezopasnosti-v-lesah', 'Правила пожарной безопасности в лесах', 'Что запрещено делать в лесу в пожароопасный сезон, как правильно развести костёр и какие штрафы грозят за нарушения.', '<p>Девять из десяти лесных пожаров в области возникают по вине людей. Правила пожарной безопасности в лесах утверждены постановлением Правительства РФ от 07.10.2020 № 1614 и обязательны для всех, кто находится в лесу.</p>
<h2>В пожароопасный сезон запрещено</h2>
<ul>
<li>бросать горящие спички, окурки и горячую золу из курительных трубок;</li>
<li>разводить костры в хвойных молодняках, на гарях, в местах с подсохшей травой и под кронами деревьев;</li>
<li>оставлять в лесу промасленную ветошь, стекло и мусор;</li>
<li>выжигать траву на лесных полянах и примыкающих к лесу участках;</li>
<li>заправлять топливом технику при работающем двигателе.</li>
</ul>
<h2>Как развести костёр безопасно</h2>
<p>Костёр разводят на площадке, очищенной от сухой травы и веток в радиусе не менее 2 метров, а если её окружает минерализованная полоса — не менее 0,4 метра шириной. Рядом должны быть средства тушения: вода, лопата или огнетушитель. Уходя, залейте угли водой и убедитесь, что они не тлеют.</p>
<h2>Ответственность</h2>
<p>За нарушение правил пожарной безопасности в лесах для граждан предусмотрен штраф от 15 до 30 тысяч рублей (статья 8.32 КоАП РФ), а в период особого противопожарного режима — до 50 тысяч рублей. Если пожар уничтожил лесные насаждения, может наступить уголовная ответственность.</p>
<div class="warning">Обнаружили возгорание — звоните <strong>8-800-100-94-00</strong> или <strong>112</strong>.</div>', 'citizens-pravila-pozharnoy-bezopasnosti-v-lesah.jpg', NULL, 2, 111, '2025-11-05 09:10');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (24, 4, 'kak-soobschit-o-nezakonnoy-rubke', 'Как сообщить о незаконной рубке', 'Что считается незаконной рубкой, как проверить, есть ли у лесозаготовителей разрешение, и куда обращаться.', '<p>Незаконная рубка — это рубка без договора, проекта освоения лесов или лесной декларации, а также рубка за пределами отведённой лесосеки. Каждое сообщение граждан проверяется: в 2025 году около трети выявленных фактов стали известны именно благодаря жителям области.</p>
<h2>Как понять, что рубка незаконная</h2>
<ul>
<li>работы ведутся ночью или в выходные дни, техника стоит без опознавательных знаков;</li>
<li>на месте рубки нет деляночных столбов и визиров (зарубок на деревьях по границе лесосеки);</li>
<li>вырубаются отдельные ценные деревья в зелёной зоне, возле водоёмов или в защитных лесах.</li>
</ul>
<p>Проверить законность рубки можно на публичной карте федеральной государственной информационной системы лесного комплекса (ФГИС ЛК): там публикуются сведения о разрешённых лесосеках с их границами. Если сомневаетесь — уточните в ближайшем лесничестве.</p>
<h2>Куда сообщить</h2>
<ol>
<li>Позвоните на прямую линию лесной охраны 8-800-100-94-00 или в ближайшее лесничество.</li>
<li>Если рубка идёт прямо сейчас, одновременно сообщите в полицию по номеру 102.</li>
<li>Сохраните фотографии, координаты места и номера машин — они помогут инспекторам.</li>
</ol>
<p>Письменное сообщение можно направить через <a href="/appeals">интернет-приёмную</a>, выбрав тематику «Незаконная рубка и лесонарушения». Вы получите ответ о результатах проверки.</p>', 'citizens-kak-soobschit-o-nezakonnoy-rubke.jpg', NULL, 2, 148, '2025-11-05 09:20');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (25, 4, 'sbor-gribov-i-yagod', 'Сбор грибов, ягод и лекарственных растений', 'Можно ли собирать грибы и ягоды бесплатно, сколько разрешено собрать и где сбор ограничен.', '<p>Граждане имеют право свободно и бесплатно находиться в лесах и собирать для собственных нужд дикорастущие плоды, ягоды, орехи, грибы и лекарственные растения (статьи 11 и 35 Лесного кодекса РФ). Разрешение для этого не требуется.</p>
<h2>Где сбор ограничен</h2>
<ul>
<li>на территории заповедников и в особо охраняемых зонах национальных парков;</li>
<li>на лесных участках, переданных в аренду для заготовки пищевых лесных ресурсов, — если об этом предупреждают аншлаги;</li>
<li>в периоды ограничения пребывания граждан в лесах из-за высокой пожарной опасности.</li>
</ul>
<h2>Правила бережного сбора</h2>
<p>Грибы лучше срезать ножом, не разрушая грибницу. Ягоды собирают только спелые, не обрывая побеги, а чернику и бруснику не стоит собирать гребёнками-комбайнами: они повреждают кустарнички, и следующий урожай будет хуже. Лекарственные растения, внесённые в Красную книгу Заречной области, собирать запрещено.</p>
<blockquote>Отправляясь в лес, предупредите близких о маршруте, возьмите заряженный телефон и воду. Если заблудились — оставайтесь на месте и звоните 112.</blockquote>', 'citizens-sbor-gribov-i-yagod.jpg', NULL, 2, 185, '2025-11-05 09:30');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (26, 4, 'arenda-lesnogo-uchastka', 'Как взять лесной участок в аренду', 'Пошаговая инструкция для граждан и предпринимателей: выбор участка, аукцион, договор и проект освоения лесов.', '<p>Лесной участок можно арендовать для отдыха и туризма, выращивания лесных ягод и грибов, пчеловодства, заготовки древесины и других целей. Срок аренды — от 10 до 49 лет, а для заготовки древесины — до 99 лет.</p>
<h2>Порядок действий</h2>
<ol>
<li><strong>Выберите участок.</strong> Посмотрите карту лесничеств и лесохозяйственные регламенты: в них указано, какие виды использования разрешены в конкретных кварталах.</li>
<li><strong>Подайте заявление о проведении аукциона</strong> в департамент. К нему прикладывается схема расположения участка.</li>
<li><strong>Дождитесь постановки участка на кадастровый учёт</strong> и публикации извещения об аукционе на сайте torgi.gov.ru.</li>
<li><strong>Примите участие в аукционе.</strong> Победитель заключает договор аренды по предложенной им цене.</li>
<li><strong>Разработайте проект освоения лесов</strong> и получите на него положительное заключение государственной экспертизы — без этого пользоваться участком нельзя.</li>
</ol>
<h2>Сколько это стоит</h2>
<p>Плата рассчитывается по ставкам, утверждённым постановлением Правительства РФ, с учётом коэффициентов. Для рекреационного участка площадью 1 гектар в зелёной зоне Заречинска годовая арендная плата в 2025 году составляла около 14 тысяч рублей.</p>
<p>Консультацию можно получить в отделе лесопользования и аренды: +7 (3800) 41-02-22.</p>', 'citizens-arenda-lesnogo-uchastka.jpg', NULL, 2, 222, '2025-11-05 09:40');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (27, 4, 'uchastie-v-posadke-lesa', 'Как принять участие в посадке леса', 'Весной и осенью департамент проводит акции по посадке леса. Рассказываем, как присоединиться волонтёру, школе или компании.', '<p>Ежегодно весной и осенью в области проходят акции «Сохраним лес» и «Сад памяти». Сажать деревья может любой желающий — опыт не нужен, инструмент и посадочный материал выдаются на месте, а специалисты лесничества показывают, как правильно работать мечом Колесова и сажать сеянцы с закрытой корневой системой.</p>
<h2>Как записаться</h2>
<ul>
<li><strong>Волонтёрам</strong> — зарегистрироваться на мероприятие в разделе «Новости» или по телефону ближайшего лесничества.</li>
<li><strong>Школам и вузам</strong> — направить заявку через <a href="/appeals">интернет-приёмную</a> с указанием числа участников. Для детей подбираются участки рядом с дорогой.</li>
<li><strong>Компаниям</strong> — согласовать корпоративную посадку с отделом воспроизводства лесов: +7 (3800) 41-02-31.</li>
</ul>
<h2>Что взять с собой</h2>
<p>Удобную одежду и закрытую обувь, перчатки, воду и средства от клещей. Одна посадка длится 3–4 часа, за это время команда из 20 человек высаживает около гектара леса — это примерно 3 тысячи сеянцев.</p>', 'citizens-uchastie-v-posadke-lesa.jpg', NULL, 2, 259, '2025-11-05 09:50');

-- Раздел «Документы»
INSERT INTO sections (id, slug, title, description, sort) VALUES (5, 'documents', 'Документы', 'Законы, постановления и приказы, регулирующие лесные отношения в Заречной области.', 5);
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (28, 5, 'lesnoy-kodeks-rf', 'Лесной кодекс Российской Федерации', 'Основной закон, регулирующий использование, охрану, защиту и воспроизводство лесов в России.', '<p>Лесной кодекс Российской Федерации определяет правовые основы использования, охраны, защиты и воспроизводства лесов, а также порядок предоставления лесных участков и распределение полномочий между Российской Федерацией и её субъектами.</p>
<h2>Статьи, к которым чаще всего обращаются граждане</h2>
<ul>
<li>статья 11 — право граждан свободно и бесплатно пребывать в лесах;</li>
<li>статья 30 — заготовка гражданами древесины для собственных нужд;</li>
<li>статья 35 — заготовка и сбор пищевых лесных ресурсов;</li>
<li>статья 53.1 — предупреждение лесных пожаров;</li>
<li>статья 83 — полномочия, переданные органам государственной власти субъектов.</li>
</ul>
<p>Актуальная редакция кодекса размещена на официальном интернет-портале правовой информации pravo.gov.ru.</p>', NULL, 'Федеральный закон от 04.12.2006 № 200-ФЗ', 1, 296, '2025-11-06 09:00');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (29, 5, 'pravila-pozharnoy-bezopasnosti-1614', 'Правила пожарной безопасности в лесах', 'Требования пожарной безопасности, которые обязаны соблюдать граждане, организации и арендаторы лесных участков.', '<p>Правила устанавливают требования пожарной безопасности при использовании, охране, защите и воспроизводстве лесов, а также при пребывании граждан в лесах.</p>
<h2>Основные положения</h2>
<ul>
<li>пожароопасный сезон начинается со дня схода снежного покрова и заканчивается с наступлением устойчивой дождливой осенней погоды или образованием снежного покрова;</li>
<li>определены места, где запрещено разводить костры, и требования к подготовке костровой площадки;</li>
<li>установлены обязанности арендаторов: создание противопожарных разрывов, минерализованных полос, наличие средств пожаротушения;</li>
<li>предусмотрена обязанность граждан при обнаружении пожара немедленно сообщить о нём и по возможности принять меры по тушению.</li>
</ul>
<p>Краткая памятка для граждан — в материале <a href="/citizens/pravila-pozharnoy-bezopasnosti-v-lesah">«Правила пожарной безопасности в лесах»</a>.</p>', NULL, 'Постановление Правительства РФ от 07.10.2020 № 1614', 1, 73, '2025-11-06 09:05');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (30, 5, 'polozhenie-o-departamente', 'Положение о департаменте лесного хозяйства Заречной области', 'Учредительный документ департамента: статус, задачи, полномочия, порядок руководства и финансирования.', '<p>Положение определяет правовой статус департамента как исполнительного органа Заречной области, осуществляющего государственное управление в области лесных отношений.</p>
<h2>Структура документа</h2>
<ol>
<li>Общие положения.</li>
<li>Основные задачи департамента.</li>
<li>Полномочия департамента.</li>
<li>Права департамента.</li>
<li>Организация деятельности.</li>
<li>Ответственность.</li>
</ol>
<p>Последние изменения, внесённые в апреле 2025 года, закрепили за департаментом функции оператора региональной системы видеомониторинга лесных пожаров и уточнили порядок взаимодействия с органами местного самоуправления.</p>', NULL, 'Постановление правительства Заречной области от 18.03.2019 № 112-п (ред. от 14.04.2025)', 1, 110, '2025-11-06 09:10');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (31, 5, 'lesnoy-plan', 'Лесной план Заречной области на 2019–2028 годы', 'Документ стратегического планирования: цели и задачи лесного хозяйства области, зонирование территории, планируемые объёмы использования лесов.', '<p>Лесной план — основной документ лесного планирования в регионе. Он определяет цели и задачи лесного хозяйства, а также планируемые мероприятия по освоению, охране, защите и воспроизводству лесов на десять лет.</p>
<h2>Ключевые показатели плана</h2>
<table>
<thead><tr><th>Показатель</th><th>Значение к 2028 году</th></tr></thead>
<tbody>
<tr><td>Лесистость территории</td><td>не ниже 57,3 %</td></tr>
<tr><td>Отношение площади лесовосстановления к площади вырубленных и погибших лесов</td><td>100 %</td></tr>
<tr><td>Доля крупных лесных пожаров в общем числе пожаров</td><td>не более 5 %</td></tr>
<tr><td>Использование расчётной лесосеки</td><td>62 %</td></tr>
</tbody>
</table>
<p>В плане выделены зоны интенсивного освоения лесов на юге области и зоны с ограниченным использованием — защитные леса вдоль рек и вокруг населённых пунктов.</p>', NULL, 'Указ губернатора Заречной области от 26.12.2018 № 245 (ред. от 20.12.2024)', 1, 147, '2025-11-06 09:15');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (32, 5, 'zakon-o-normativah-zagotovki', 'О нормативах заготовки гражданами древесины для собственных нужд', 'Закон устанавливает порядок и нормативы заготовки древесины гражданами для отопления, строительства и ремонта жилых домов и хозяйственных построек.', '<p>Закон принят в соответствии с частью 5 статьи 30 Лесного кодекса Российской Федерации и регулирует отношения, связанные с заготовкой гражданами древесины для собственных нужд на территории Заречной области.</p>
<h2>Основные положения</h2>
<ul>
<li>установлены нормативы заготовки для строительства жилого дома, его ремонта, строительства хозяйственных построек и отопления;</li>
<li>определён перечень документов, прилагаемых к заявлению;</li>
<li>установлен срок рассмотрения заявления — 15 рабочих дней;</li>
<li>предусмотрены основания для отказа: повторное обращение до истечения установленного срока, отсутствие права на заготовку, недостоверные сведения в заявлении.</li>
</ul>
<p>Таблица нормативов приведена в материале <a href="/citizens/zagotovka-drevesiny-dlya-sobstvennyh-nuzhd">«Заготовка древесины для собственных нужд»</a>.</p>', NULL, 'Закон Заречной области от 30.06.2022 № 41-ЗО', 1, 184, '2025-11-06 09:20');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (33, 5, 'reglament-dogovory-kupli-prodazhi', 'Административный регламент «Заключение договоров купли-продажи лесных насаждений для собственных нужд граждан»', 'Порядок и сроки предоставления государственной услуги, перечень документов, основания для отказа и порядок обжалования.', '<p>Регламент устанавливает стандарт предоставления государственной услуги по заключению договоров купли-продажи лесных насаждений для собственных нужд граждан и последовательность действий лесничеств.</p>
<h2>Стандарт услуги</h2>
<table>
<thead><tr><th>Параметр</th><th>Значение</th></tr></thead>
<tbody>
<tr><td>Заявители</td><td>граждане, имеющие право на заготовку древесины в соответствии с законом области</td></tr>
<tr><td>Срок предоставления</td><td>15 рабочих дней</td></tr>
<tr><td>Способы подачи</td><td>лично в лесничестве, через МФЦ, через портал Госуслуг</td></tr>
<tr><td>Результат</td><td>договор купли-продажи лесных насаждений или мотивированный отказ</td></tr>
<tr><td>Плата за услугу</td><td>не взимается (оплачивается только стоимость древесины)</td></tr>
</tbody>
</table>
<p>Решения и действия должностных лиц можно обжаловать директору департамента или в суде.</p>', NULL, 'Приказ департамента лесного хозяйства Заречной области от 14.02.2024 № 58', 1, 221, '2025-11-06 09:25');
INSERT INTO articles (id, section_id, slug, title, summary, body, image, doc_meta, author_id, views, published_at) VALUES (34, 5, 'plan-tusheniya-pozharov-2026', 'Сводный план тушения лесных пожаров на территории Заречной области на 2026 год', 'Порядок привлечения сил и средств для тушения лесных пожаров, схема взаимодействия служб и резервы на пожароопасный сезон 2026 года.', '<p>Сводный план определяет перечень и состав лесопожарных формирований, пожарной техники и оборудования, порядок их привлечения и маневрирования, а также схему оповещения при возникновении лесных пожаров.</p>
<h2>Силы и средства на сезон 2026 года</h2>
<ul>
<li>9 пожарно-химических станций ГАУ «Заречный лесопожарный центр», из них 3 станции III типа;</li>
<li>412 человек в составе лесопожарных формирований, включая 48 десантников-пожарных;</li>
<li>137 единиц пожарной и приспособленной для тушения техники;</li>
<li>резерв горюче-смазочных материалов и продуктов питания на 10 суток работы.</li>
</ul>
<p>План согласован с Федеральным агентством лесного хозяйства и Главным управлением МЧС России по Заречной области.</p>', NULL, 'Указ губернатора Заречной области от 12.12.2025 № 198', 1, 258, '2025-12-16 09:00');

