INSERT INTO appeals (id, user_id, category, subject, status, assigned_to, created_at, updated_at) VALUES (1, 4, 'Заготовка древесины для собственных нужд', 'Сроки заключения договора на дрова', 'answered', 2, '2025-12-22 19:05', '2025-12-23 12:10');
INSERT INTO appeal_messages (id, appeal_id, user_id, body, created_at) VALUES (1, 1, 4, 'Здравствуйте! В начале декабря подала заявление в Озёрское лесничество на заготовку дров для отопления дома (20 кубометров). Прошло уже больше двух недель, договор так и не прислали. Подскажите, в какие сроки должны рассмотреть заявление и куда обращаться, если сроки нарушены?', '2025-12-22 19:05');
INSERT INTO appeal_messages (id, appeal_id, user_id, body, created_at) VALUES (2, 1, 2, 'Наталья Сергеевна, добрый день! Срок рассмотрения заявления — 15 рабочих дней со дня регистрации. Ваше заявление зарегистрировано 5 декабря, поэтому срок истекает 25 декабря. Мы уточнили в Озёрском лесничестве: договор подготовлен и 24 декабря будет направлен вам на подпись через портал Госуслуг. Если договор не поступит, сообщите об этом в этой переписке.', '2025-12-23 11:30');
INSERT INTO appeal_messages (id, appeal_id, user_id, body, created_at) VALUES (3, 1, 4, 'Спасибо, буду ждать.', '2025-12-23 12:02');
INSERT INTO appeal_messages (id, appeal_id, user_id, body, created_at) VALUES (4, 1, 2, 'Пожалуйста. После оплаты не забудьте получить в лесничестве разметку лесосеки.', '2025-12-23 12:10');
INSERT INTO appeals (id, user_id, category, subject, status, assigned_to, created_at, updated_at) VALUES (2, 4, 'Незаконная рубка и лесонарушения', 'Свалка мусора у дороги на Озёрное', 'in_work', 3, '2025-12-24 09:47', '2025-12-24 09:47');
INSERT INTO appeal_messages (id, appeal_id, user_id, body, created_at) VALUES (5, 2, 4, 'На 12-м километре дороги Заречинск — Озёрное, справа по ходу движения, в лесу за придорожной полосой образовалась свалка строительного мусора: старые окна, мешки, шифер. Прошу принять меры.', '2025-12-24 09:47');
INSERT INTO appeals (id, user_id, category, subject, status, assigned_to, created_at, updated_at) VALUES (3, 5, 'Работа сайта', 'Предложение по разделу «Гражданам»', 'closed', 2, '2025-12-23 10:20', '2025-12-23 15:45');
INSERT INTO appeal_messages (id, appeal_id, user_id, body, created_at) VALUES (6, 3, 5, 'Добрый день. Хорошо бы добавить на сайт материал о том, как взять участок под пасеку. Не нашёл такой информации.', '2025-12-23 10:20');
INSERT INTO appeal_messages (id, appeal_id, user_id, body, created_at) VALUES (7, 3, 2, 'Олег Константинович, спасибо за предложение! Порядок предоставления участков для пчеловодства кратко описан в материале «Использование лесов и аренда лесных участков» (раздел «Деятельность»). Подробную инструкцию мы подготовим и опубликуем в январе.', '2025-12-23 15:45');

